function occurrenceId(planId,date){return `${planId}@${date}`;}
// Credit-card purchases belong to their purchase month and accrue a liability
// immediately; the bank account is debited on the 15th of the following month.
// We derive a SINGLE deterministic settlement from the saved purchases and the
// initial debt. No ledger entries are inserted each time the app is opened.
// A manual settlement for the same period takes precedence, preventing double
// debits for archives where the user already paid the credit-card statement.
function automaticCardPayments(data,day){
  if(!isValidDate(day)||day<data.startDate||data.card?.autoDebitEnabled===false)return [];
  const totals=new Map();
  const charge=(period,amount)=>{
    if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))return;
    const due=cardDueDate(period);
    if(due<data.startDate||due>day)return;
    const value=Number(amount);
    if(!Number.isFinite(value)||value<=0)return;
    totals.set(period,eurRound((totals.get(period)||0)+value));
  };
  const opening=Number(data.card?.openingDebt);
  if(data.card?.openingDebt!==null&&data.card?.openingDebt!==undefined && Number.isFinite(opening))
    charge(data.card.openingPeriod||'2026-10',opening);
  const manuallySettled=new Set();
  for(const event of data.movements||[]){
    if(event.status==='skipped'||event.status==='historical')continue;
    if(event.type==='card_payment')manuallySettled.add(event.period||monthKey(event.date));
    if(event.type==='card_purchase'&&event.date>=data.startDate&&event.date<=day)
      charge(monthKey(event.date),event.amount);
  }
  const exceptions=data.card?.autoDebitExceptions||{};
  return [...totals].filter(([period,amount])=>amount>0.005&&!manuallySettled.has(period)&&!exceptions[period]).map(([period,amount])=>({
    id:`card-auto@${period}`,date:cardDueDate(period),type:'card_payment',from:'allianz',
    period,amount:eurRound(amount),note:`Addebito carta automatico · ${period}`,
    status:'planned',automatic:true,automaticCardDebit:true
  })).sort((a,b)=>a.date.localeCompare(b.date));
}

function card(x){
  const periods=Object.entries(x.card.byPeriod).sort((a,b)=>b[0].localeCompare(a[0]));
  const dueList=periods.filter(([period,amount])=>amount>0.005).map(([period])=>cardDueDate(period)).filter(Boolean).sort();
  const earliestDue=dueList[0]||'';
  const entries=[...x.card.purchases].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10);
  const thisMonth=eurRound(x.card.purchases.filter(o=>monthKey(o.date)===monthKey(dNow())).reduce((s,o)=>s+Number(o.amount||0),0));
  const autoPayMap=Object.fromEntries(x.card.payments.filter(o=>o.automaticCardDebit).map(o=>[o.period,o]));
  const manualPayPeriods=new Set(x.card.payments.filter(o=>!o.automaticCardDebit).map(o=>o.period||monthKey(o.date)));
  const exceptions=state.card?.autoDebitExceptions||{};
  const periodRow=([period,n])=>{
    const due=cardDueDate(period),automatic=autoPayMap[period],blocked=!!exceptions[period],manual=manualPayPeriods.has(period),future=due>dNow();
    const info=automatic?`Addebito stimato ${fmtDate(due)} · ${money(automatic.amount)} · non verificato in banca`:
      blocked?'Automatismo sospeso: movimento non avvenuto':
      manual?'Presente un addebito manuale: automatismo escluso per evitare duplicati':
      `Addebito automatico previsto ${fmtDate(due)} su Allianz Bank`;
    const action=automatic?`<button class="btn ghost small" data-action="cardnotpaid" data-id="${e(period)}">Non avvenuto</button>`:
      blocked?`<button class="btn secondary small" data-action="paycard" data-id="${e(period)}">Registra addebito reale</button><button class="btn ghost small" data-action="cardresume" data-id="${e(period)}">Riattiva automatico</button>`:
      n>0.005?`<span class="token ${manual?'orange':'blue'}">${manual?'Pagamento manuale':future?'Automatico il 15':'Da verificare'}</span>${manual?`<button class="btn ghost small" data-action="paycard" data-id="${e(period)}">Completa manualmente</button>`:''}`:
      `<span class="token green">Saldato</span>`;
    return `<div class="data-row"><div class="item-main"><div class="item-name">${e(period)}</div><div class="item-meta">${e(info)}</div></div><div class="item-val">${money(n)}</div><div style="display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end">${action}</div></div>`;
  };
  return `${heading('Carta di credito','Le spese vengono conteggiate alla data di acquisto; l’addebito su Allianz è calcolato automaticamente il 15 del mese dopo.','Nuova spesa','addcard')}<div class="stack">
    <div class="inline-alert info"><strong>Addebiti automatici attivi.</strong> Gli acquisti di ogni mese vengono addebitati su Allianz il <strong>15 del mese successivo</strong> (per esempio ottobre → 15 novembre), anche se apri l’app qualche giorno dopo. Contemporaneamente verrà estinto il relativo debito: il patrimonio netto non subirà una seconda riduzione. <strong>È una contabilizzazione prevista</strong>, non una conferma dell’addebito bancario.</div>
    <div class="grid three">${metric('Debito residuo',money(x.card.value),'💳','Al netto degli addebiti previsti già maturati')}${metric('Acquisti mese corrente',money(thisMonth),'🧾','Spese registrate, indipendentemente dai pagamenti')}${metric('Prima scadenza aperta',fmtDate(earliestDue),'📅',earliestDue?'Da addebitare su Allianz':'Nessuna scadenza aperta')}</div>
    ${x.card.unknownOpening?'<div class="inline-alert">Indica il debito iniziale della carta al 16 ottobre 2026: senza quel dato la situazione completa potrebbe essere sottostimata. <button class="mini-link" data-action="cardopening">Imposta debito iniziale →</button></div>':''}
    <section class="panel"><div class="panel-head"><h2 class="panel-title">Scadenze e addebiti automatici</h2><button class="btn ghost small" data-action="cardopening">Modifica apertura</button></div>${periods.length?`<div class="rows">${periods.map(periodRow).join('')}</div>`:'<div class="empty">Non risultano ancora spese con carta.</div>'}<div class="micro lower">Se hai già registrato manualmente l'addebito di un mese, My Wealth non ne crea un secondo. Per correggere una scadenza contabilizzata automaticamente come non avvenuta, usa il pulsante dedicato.</div></section>
    <section class="panel"><div class="panel-head"><h2 class="panel-title">Ultimi acquisti</h2></div>${entries.length?`<div class="rows">${entries.map(o=>`<div class="data-row"><div class="item-main"><div class="item-name">${e(o.note||'Acquisto con carta')}</div><div class="item-meta">${fmtDate(o.date)} · scadenza ${fmtDate(cardDueDate(monthKey(o.date)))} · ${e(categoryLabel(o))}</div></div><div class="item-val">${money(o.amount)}</div><button class="btn secondary small" data-action="editmovement" data-id="${e(o.id)}">Modifica</button></div>`).join('')}</div>`:'<div class="empty">Registra i singoli acquisti del mese oppure un unico totale cumulativo.</div>'}</section>
    </div>`;
}

function cardDebitNotOccurred(period){
  if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))throw Error('Periodo carta non valido.');
  if(cardDueDate(period)>dNow())throw Error('La scadenza non è ancora arrivata.');
  const auto=automaticCardPayments(state,dNow()).find(e=>e.period===period);
  if(!auto)return;
  if(!confirm('L’addebito della carta di '+money(auto.amount)+' previsto il '+fmtDate(auto.date)+' NON è avvenuto sul conto Allianz?\n\nIl debito tornerà aperto e il saldo Allianz verrà ripristinato.'))return;
  if(!state.card.autoDebitExceptions||typeof state.card.autoDebitExceptions!=='object')state.card.autoDebitExceptions={};
  state.card.autoDebitExceptions[period]=true;
  persist();notify('Addebito segnato come non avvenuto. Verifica con la banca e premi Salva.');
}
function resumeAutomaticCardDebit(period){
  if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))throw Error('Periodo carta non valido.');
  if(!confirm('Riattivare la contabilizzazione automatica del periodo '+period+'?\n\nSe la scadenza è passata, il saldo Allianz sarà ridotto nuovamente.'))return;
  if(!state.card.autoDebitExceptions||typeof state.card.autoDebitExceptions!=='object')state.card.autoDebitExceptions={};
  delete state.card.autoDebitExceptions[period];
  persist();notify('Addebito automatico ripristinato. Premi Salva.');
}
